import json,sys,tempfile,threading
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from playwright.sync_api import sync_playwright,expect

out=ROOT/'qa-output/file-rename-ui';out.mkdir(exist_ok=True);checks=[];errors=[]
with tempfile.TemporaryDirectory(prefix='zenit-file-rename-',ignore_cleanup_errors=True) as temp:
 root=Path(temp);project=root/'project';project.mkdir();(project/'main.py').write_text('VALUE=1\nprint(VALUE)\n');(project/'other.py').write_text('keep\n');(project/'slow.txt').write_text('slow\n');(project/'folder').mkdir();(project/'folder/note.txt').write_text('note\n')
 app=Application(ROOT,project,data_dir=root/'profile');f=app.features;app.workspace.trusted=True;f.prefs.update({'general.locale':'es','general.showWelcome':False,'updates.automatic':False,'security.confirmRoutineActions':False,'files.autoSave':False});f.studio.update({'onboarded':True})
 server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start()
 try:
  with sync_playwright() as pw:
   browser=pw.chromium.launch(channel='msedge',headless=True);page=browser.new_page(viewport={'width':1600,'height':1000});page.on('pageerror',lambda e:errors.append(str(e)))
   def inject(route):
    response=route.fetch();route.fulfill(response=response,body=response.text()+'\nwindow.__qa={get editor(){return editor},get platform(){return platformUI},get preview(){return previewUI},get pendingOpens(){return pendingFileOpens.size},openFile};')
   def rename(name):page.locator('#file-rename-name').fill(name);page.locator('#file-rename-form button[type=submit]').click()
   page.route('**/src/app.js',inject);page.goto(f'http://127.0.0.1:{server.server_port}');page.wait_for_function('window.lumen?.platformReady')
   pending=[];page.route('**/api/file?path=main.py',lambda route:pending.append(route))
   page.locator('[data-file="main.py"]').click();expect(page.locator('[data-file="main.py"]')).to_be_focused();page.keyboard.press('F2');expect(page.locator('#file-rename-name')).to_be_focused();assert page.locator('#file-rename-name').evaluate('(e)=>[e.selectionStart,e.selectionEnd]')==[0,4];assert pending;pending.pop().continue_();page.wait_for_function('__qa.editor.current==="main.py"');expect(page.locator('#file-rename-name')).to_be_focused();page.unroute('**/api/file?path=main.py')
   rename('renamed.py');expect(page.locator('[data-file="renamed.py"]')).to_be_visible();assert not (project/'main.py').exists();checks.append('Clicking an explorer file keeps tree focus; F2 selects the basename and performs a real file rename')
   page.evaluate('()=>{const ed=__qa.editor;ed.view.getModel().setValue("VALUE=42\\nprint(VALUE)\\n");ed.view.setPosition({lineNumber:2,column:5})}')
   page.evaluate('__qa.platform.api("/workbench/session",{session:window.zenitSessionSnapshot()})')
   page.locator('[data-tab="renamed.py"]').click(button='right');page.get_by_role('menuitem',name='Cambiar nombre de archivo…',exact=True).click();rename('changed.py')
   page.wait_for_function('__qa.editor.current==="changed.py"');assert page.evaluate('__qa.editor.getValue()')=='VALUE=42\nprint(VALUE)\n';assert page.evaluate('__qa.editor.isDirty("changed.py")');assert (project/'changed.py').read_text()=='VALUE=1\nprint(VALUE)\n';assert page.evaluate('__qa.editor.view.getPosition().column')==5
   checks.append('The tab menu renames the file while preserving the unsaved draft, disk bytes, cursor and recovery path')
   page.locator('[data-tab="changed.py"]').click(button='right');page.get_by_role('menuitem',name='Cambiar nombre de archivo…',exact=True).click();rename('other.py');expect(page.locator('[data-rename-error]')).to_contain_text('Ya existe');expect(page.locator('#file-rename-name')).to_have_value('other.py');assert (project/'other.py').read_text()=='keep\n';page.locator('[data-rename-cancel]').click();checks.append('A collision keeps the dialog open for correction and never overwrites the other file')
   page.evaluate('__qa.editor.view.focus()');page.keyboard.press('Shift+F10');page.locator('.editor-context-menu button').filter(has_text='Archivo').first.click();page.get_by_role('menuitem',name='Cambiar nombre de archivo…',exact=True).click();rename('Changed.py');page.wait_for_function('__qa.editor.current==="Changed.py"');assert 'Changed.py' in [p.name for p in project.iterdir()];checks.append('The editor File submenu uses the same action and supports a case-only rename on Windows')
   page.locator('[data-dir="folder"]').click(button='right');page.get_by_role('menuitem',name='Cambiar nombre…',exact=True).click();rename('source');expect(page.locator('[data-dir="source"]')).to_be_visible();assert (project/'source/note.txt').read_text()=='note\n';checks.append('Folders use the same naming workflow and retain their children')
   page.locator('[data-dir="source"]').click();page.locator('[data-file="source/note.txt"]').click();page.locator('[data-tab="source/note.txt"]').click(button='right');page.get_by_role('menuitem',name='Eliminar archivo',exact=True).click();page.locator('[data-file="source/note.txt"]').wait_for(state='detached');page.wait_for_function('!__qa.editor.models.has("source/note.txt")');assert not (project/'source/note.txt').exists()
   page.locator('.tree-root').click(button='right');page.get_by_role('menuitem',name='Deshacer eliminación',exact=True).click();page.locator('[data-file="source/note.txt"]').wait_for(state="visible");assert (project/'source/note.txt').read_text()=='note\n';checks.append('Delete from a tab closes it and Undo deletion restores the exact file from project trash')
   page.locator('[data-file="source/note.txt"]').click();page.keyboard.press('Delete');page.locator('[data-file="source/note.txt"]').wait_for(state='detached');page.wait_for_function('!__qa.editor.models.has("source/note.txt")');assert not (project/'source/note.txt').exists()
   page.evaluate('__qa.editor.view.focus()');page.keyboard.press('Shift+F10');page.locator('.editor-context-menu button').filter(has_text='Archivo').first.click();page.get_by_role('menuitem',name='Deshacer eliminación',exact=True).click();page.locator('[data-file="source/note.txt"]').wait_for(state="visible");checks.append('Supr from Project deletes the selected file and the editor submenu can restore it')
   page.locator('[data-tab="Changed.py"]').click();page.evaluate('__qa.editor.view.focus()');page.keyboard.press('Shift+F10');page.locator('.editor-context-menu button').filter(has_text='Archivo').first.click();page.get_by_role('menuitem',name='Eliminar archivo',exact=True).click();expect(page.locator('#confirm-yes')).to_have_text('Guardar y continuar');page.locator('#confirm-yes').click();page.wait_for_function('!__qa.editor.models.has("Changed.py")');assert not (project/'Changed.py').exists()
   page.locator('.tree-root').click(button='right');page.get_by_role('menuitem',name='Deshacer eliminación',exact=True).click();page.locator('[data-file="Changed.py"]').wait_for(state="visible");assert (project/'Changed.py').read_text()=='VALUE=42\nprint(VALUE)\n';checks.append('Deleting a dirty file explicitly saves its draft before moving it to trash, and Undo restores that saved draft')
   held=[]
   def hold_file(route):held.append((route,route.fetch()))
   page.route('**/api/file?path=slow.txt',hold_file);page.locator('[data-file="slow.txt"]').click();expect(page.locator('[data-file="slow.txt"]')).to_be_focused();page.keyboard.press('Delete');page.locator('[data-file="slow.txt"]').wait_for(state='detached');assert held;route,response=held.pop();route.fulfill(response=response);page.wait_for_function('__qa.pendingOpens===0');assert not page.evaluate('__qa.editor.models.has("slow.txt")');checks.append('A late file-open response cannot reopen a deleted file after a rapid click and Supr')
   event=next(row for row in reversed(f.command_events) if row.get('command')=='zenit.workspace.edit' and any(r.get('path')=='slow.txt' and r.get('kind')=='delete' for r in row.get('edit',{}).get('resources',[])))
   page.unroute('**/api/file?path=slow.txt');page.locator('.tree-root').click(button='right');page.get_by_role('menuitem',name='Deshacer eliminación',exact=True).click();page.locator('[data-file="slow.txt"]').wait_for(state='visible');page.locator('[data-file="slow.txt"]').click();page.wait_for_function('__qa.editor.current==="slow.txt"');page.evaluate('(event)=>__qa.preview.services.event(event)',event);assert page.evaluate('__qa.editor.models.has("slow.txt")');checks.append('A duplicate deletion notification cannot close a restored file')
   page.screenshot(path=str(out/'renamed-files.png'));assert not errors,errors;browser.close()
 finally:server.shutdown();server.server_close();f.shutdown();app.runner.shutdown()
(out/'report.json').write_text(json.dumps({'checks':checks,'errors':errors},ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'passed':len(checks),'errors':errors}))
